INSERT INTO `couple_kb_entries` (`id`, `entry_type`, `assessment_code`, `assessment_version`, `dimension_code`, `assessment_b_code`, `dimension_b_code`, `title`, `body_json`, `confidence`, `source_note`, `status`, `effective_date`, `created_at`, `updated_at`) VALUES
(1, 'bands', 'young-schema-full-l3', NULL, NULL, NULL, NULL, 'نوارهای شدت درصدی طرحواره‌های یانگ (YSQ-L3)', '{\"bands\":[{\"max_pct\":20,\"level\":\"normal\"},{\"max_pct\":32,\"level\":\"low\"},{\"max_pct\":48,\"level\":\"moderate\"},{\"max_pct\":68,\"level\":\"high\"},{\"max_pct\":100,\"level\":\"severe\"}]}', 'high', 'YSQ_INTERPRETATION_SPEC_FINAL_v2.1 — هم‌راستا با موتور نمره‌دهی سامانه', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(2, 'interpretation', 'young-schema-full-l3', NULL, 'sch_1', NULL, NULL, 'طرحوارهٔ محرومیت هیجانی', '{\"need\": \"نیاز به مهر، توجه و همدلی عاطفی\", \"sensitivity\": \"لحظه‌هایی که شریک زندگی از ابراز محبت غافل می‌شود یا پاسخ هیجانی نمی‌دهد، این فرد احساس تنهایی عاطفی می‌کند.\", \"partner_sees\": \"شریک ممکن است احساس کند هرگز به‌اندازهٔ کافی محبت نمی‌کند یا انتظارات عاطفی بی‌پایان است.\", \"resource\": \"توانایی شناخت دقیق نیازهای عاطفی خود و دیگران\", \"question\": \"در چه موقعیت‌هایی احساس می‌کنید همسرتان «هیچ‌وقت» نیاز عاطفی شما را نمی‌بیند؟\", \"activation\": {\"when\": \"در لحظه‌هایی که نیاز عاطفی او دیده نمی‌شود؛ به‌ویژه در روابط نزدیک، وقتی انتظار گرمی و همدلی دارد و پاسخ سرد، کاربردی یا عجول می‌گیرد.\", \"triggers\": [\"بی‌توجهی به احساسات او\", \"پاسخ‌های کوتاه و خشک به حرف‌های عاطفی\", \"فراموش‌شدن تاریخ‌ها و خواسته‌های مهم او\", \"بیانِ آسیب‌دیدگی که جدی گرفته نمی‌شود\"], \"thoughts\": [\"هیچ‌کس واقعاً من را نمی‌فهمد\", \"نیازهایم برای دیگران سنگین و زیاد است\", \"در این رابطه با وجود حضورِ دیگری، عاطفی تنها هستم\"], \"emotions\": [\"تنهایی عمیق\", \"غم و حس خالی‌بودن\", \"خشم پنهان از دیده‌نشدن\"], \"coping_mode\": \"تسلیم\", \"coping_examples\": [\"تحمل سردی و خاموش‌ماندنِ نیاز\", \"سعی در راضی‌نگه‌داشتنِ دیگران بدون گفتنِ خواستهٔ خود\"], \"situations\": [\"شب‌هایی که گفت‌وگو به برنامه‌ریزی خانه خلاصه می‌شود\", \"بعد از یک روز سخت که همسر متوجه حال او نشد\", \"مناسبت‌ها و جشن‌ها که دیده‌نشدن برجسته می‌شود\"], \"couple_trigger\": \"پاسخِ توصیه‌محور یا کاربردی به‌جای همدلی از سمت همسر\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(3, 'interpretation', 'young-schema-full-l3', NULL, 'sch_2', NULL, NULL, 'طرحوارهٔ رهاشدگی / بی‌ثباتی', '{\"need\": \"نیاز به ثبات، پیش‌بینی‌پذیری و اطمینان از تداوم رابطه\", \"sensitivity\": \"تأخیر در پاسخ، غیبت‌های کوتاه یا فاصله‌گیری موقت می‌تواند اضطراب شدید جدایی برانگیزد.\", \"partner_sees\": \"شریک ممکن است خود را تحت نظارت، پیگیری مکرر یا نیازمند اطمینان‌بخشی دائمی ببیند.\", \"resource\": \"ارتباط عمیق با هیجان‌ها و اهمیت فراوان برای پیوند عاطفی\", \"question\": \"وقتی همسرتان دیر پاسخ می‌دهد یا در دسترس نیست، در ذهن و بدنتان چه اتفاقی می‌افتد؟\", \"activation\": {\"when\": \"هر وقت دسترسی به شخص دلبسته مختل شود — تأخیر در پاسخ، غیبت، فاصلهٔ عاطفی، یا هر نشانه‌ای که «احتمال ترک شدن» را روشن کند.\", \"triggers\": [\"دیر جواب‌دادن به تماس و پیام\", \"غیبت و برگشتِ بدون زمانِ مشخص\", \"قهر و قطع رابطهٔ موقت\", \"تعریف همسر از افراد جدید یا فضای بدون او\"], \"thoughts\": [\"می‌خواهد مرا ترک کند\", \"دیگر مثل قبل نیست\", \"حالا که زحمت دادم، رهایم می‌کند\", \"باید کاری کنم که نرود\"], \"emotions\": [\"اضطراب شدید و دل‌شورهٔ جدایی\", \"هراس از تنها ماندن\", \"خشم جلوه‌گرانه روی ترسِ پنهان\"], \"coping_mode\": \"بیش‌جبرانی\", \"coping_examples\": [\"چسبندگی، تماس‌های پیاپی و سؤال‌های تکراری\", \"کنترل و چک‌کردن (گوشی، برنامه، رفتار)\", \"تسلیم‌نشدن در دعوا برای نماندنِ طرف\"], \"situations\": [\"غیبت‌های کاری همسر\", \"شب‌هایی که همسر دیر برمی‌گردد\", \"بعد از هر قهر — زنجیرهٔ پیام‌ها و تماس‌ها\"], \"couple_trigger\": \"فاصله، غیبت یا بی‌پاسخی همسر\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(4, 'interpretation', 'young-schema-full-l3', NULL, 'sch_3', NULL, NULL, 'طرحوارهٔ بی‌اعتمادی / بدرفتاری', '{\"need\": \"نیاز به امنیت و اعتماد در رابطه\", \"sensitivity\": \"اشتباهات کوچک یا ابهام در رفتار شریک به‌راحتی به «قصد آسیب‌زننده» تعبیر می‌شود.\", \"partner_sees\": \"شریک ممکن است احساس بی‌گناهی متهم‌شده، بازجویی‌شده یا بی‌اعتمادی دائمی کند.\", \"resource\": \"هوشیاری بالا نسبت به نشانه‌های خطر و مرزهای شخصی\", \"question\": \"چه تجربه‌هایی باعث شده اعتماد کردن سخت شود؟ چه چیزی به شما کمک می‌کند احساس امنیت کنید؟\", \"activation\": {\"when\": \"وقتی سیگنالی از پنهان‌کاری، دروغ یا سوءاستفاده ببیند — حتی جزئی؛ یا وقتی قرار است خودش را آسیب‌پذیر نشان دهد و ریسک «سوءاستفاده از ضعف» بالا می‌رود.\", \"triggers\": [\"قفل‌بودن گوشی یا حریم‌های غیرشفاف\", \"تناقض بین حرف‌ها و رفتارها\", \"دیر خبر دادن یا کتمانِ بخشی از ماجرا\", \"آشنایی تازه یا فضای بدونِ اطلاعِ او\"], \"thoughts\": [\"دارم فریب می‌خورم\", \"زود یا دیر ضرر می‌کنم\", \"نباید ضعفم را نشان دهم\", \"باید همیشه آماده باشم\"], \"emotions\": [\"بدگمانی و گوش‌به‌زنگی\", \"خشم دفاعی\", \"اضطراب روی ترسِ آسیب‌دیدن\"], \"coping_mode\": \"بیش‌جبرانی\", \"coping_examples\": [\"بازرسی و امتحان‌کردن طرف مقابل\", \"پیش‌دستی در حمله یا تهمت\", \"یا در الگوی اجتنابی: دیوار کشیدن و اشتراک‌نکردن اطلاعات\"], \"situations\": [\"گفت‌وگوهای مهمی که به بازجویی می‌کشد\", \"وقتی همسر دیر و ناقص خبر می‌دهد\", \"بعد از یک دروغ یا خیانت واقعی در گذشته — بازتأیید طرحواره\"], \"couple_trigger\": \"پنهان‌کاری جزئی یا شفافیت‌نکردن\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(5, 'interpretation', 'young-schema-full-l3', NULL, 'sch_4', NULL, NULL, 'طرحوارهٔ انزوای اجتماعی / بیگانگی', '{\"need\": \"نیاز به تعلق و پذیرفته‌شدن در جمع\", \"sensitivity\": \"مهمانی‌ها و موقعیت‌های اجتماعی مشترک ممکن است احساس بیگانگی و اضطراب ایجاد کند.\", \"partner_sees\": \"شریک ممکن است تمایل به دوری از فعالیت‌های اجتماعی مشترک را بی‌علاقگی تفسیر کند.\", \"resource\": \"استقلال فکری و توانایی همراهی با متفاوت‌ها بدون تقلید\", \"question\": \"در جمع‌های مشترک، چه حسی دارید و چه چیزی آن را آسان‌تر می‌کند؟\", \"activation\": {\"when\": \"در جمع‌ها و موقعیت‌های اجتماعی، یا هر جا مقایسه با دیگران حس «متفاوت بودن و جا نداشتن» روشن می‌کند.\", \"triggers\": [\"مهمانی و جمع‌های پررفت‌وآمد\", \"حس قضاوت‌شدنی بودن\", \"نبودِ هم‌نوا بودن با موضوعات جمع\", \"مقایسه با زوج‌ها یا خانواده‌های دیگر\"], \"thoughts\": [\"من با این‌ها فرق دارم\", \"جایم این‌جا نیست\", \"هیچ‌کس دنیای مرا نمی‌فهمد\"], \"emotions\": [\"تنهایی و بی‌تعارفِ بیگانه بودن\", \"غمِ پنهان زیر غرور\", \"اضطراب اجتماعی\"], \"coping_mode\": \"اجتناب\", \"coping_examples\": [\"نرفتن به جمع‌ها یا زودتر خارج شدن\", \"فاصله گرفتن و ساکت نشستن\", \"بهانه‌آوردن برای برنامه‌های اجتماعی\"], \"situations\": [\"مهمانی‌های خانوادهٔ همسر\", \"جمع‌های کاری همسر\", \"سفرها و دورهمی‌های دسته‌جمعی\"], \"couple_trigger\": \"برنامه‌های اجتماعی مشترک و جمع‌های جدید\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(6, 'interpretation', 'young-schema-full-l3', NULL, 'sch_5', NULL, NULL, 'طرحوارهٔ نقص / شرم', '{\"need\": \"نیاز به پذیرش بی‌قید و ارزشمندی ذاتی\", \"sensitivity\": \"هر انتقاد، مقایسه یا نگاه تند می‌تواند به «اثبات معیوب‌بودن من» تبدیل شود.\", \"partner_sees\": \"شریک ممکن است با جبهه‌گیری شدید در برابر انتقادهای به‌ظاهر کوچک غافلگیر شود.\", \"resource\": \"حساسیت به رنج دیگران و توان همدلی عمیق\", \"question\": \"وقتی از شما انتقاد می‌شود، آن انتقاد دربارهٔ «آن رفتار» است یا دربارهٔ «کل وجود شما»؟\", \"activation\": {\"when\": \"وقتی معایب احتمالی او در آستانهٔ «دیده شدن» است — نقد، مقایسه، اشتباه عمومی یا رد شدن.\", \"triggers\": [\"انتقاد همسر، حتی شوخیِ تحقیرآمیز\", \"مقایسه با دیگران\", \"اشتباه کردن جلوی جمع\", \"کاهش توجه و علاقهٔ ظاهری همسر\"], \"thoughts\": [\"اگر واقعاً مرا ببیند، دیگر دوستم نخواهد داشت\", \"من ایراد ذاتی دارم\", \"باید کاری کنم کمتر نقد شوم\"], \"emotions\": [\"شرم و خجالت\", \"حس بی‌ارزشی\", \"اضطرابِ رودرویی و خشم پنهان از قضاوت\"], \"coping_mode\": \"اجتناب\", \"coping_examples\": [\"پنهان‌کاری و جلوه‌سازی\", \"تعارف افراطی یا کمال‌گرایی ظاهری\", \"یا تسلیم: پذیرفتن تحقیر به‌عنوان سهم خود\"], \"situations\": [\"جلسات خانوادگیِ قضاوت‌محور\", \"بعد از انتقاد دربارهٔ ظاهر، خانه یا فرزندپروری\", \"موقعیت‌های رقابتی و ارزیابی\"], \"couple_trigger\": \"انتقاد مستقیم یا مقایسه با دیگران\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(7, 'interpretation', 'young-schema-full-l3', NULL, 'sch_6', NULL, NULL, 'طرحوارهٔ شکست', '{\"need\": \"نیاز به احساس شایستگی و موفقیت در چشم دیگران\", \"sensitivity\": \"مقایسه با زوج‌های موفق‌تر یا بحث‌های مالی\\/شغلی می‌تواند احساس شکست را فعال کند.\", \"partner_sees\": \"شریک ممکن است بی‌انگیزگی یا بهانه‌جویی ببیند؛ در حالی که زیرش باور بی‌کفایتی است.\", \"resource\": \"واقع‌بینی دربارهٔ محدودیت‌ها و اجتناب از وعده‌های غیرواقعی\", \"question\": \"در حوزه‌های موفقیت، چه جمله‌ای دربارهٔ خودتان بیشترین اثر روانی را دارد؟\", \"activation\": {\"when\": \"در موقعیت‌های ارزیابی و عملکردی، و هر مقایسه‌ای که «کم‌تر بودن نسبت به همسالان» را روشن کند.\", \"triggers\": [\"تعریف از موفقیت دیگران\", \"سؤال از شغل، درآمد یا پیشرفت\", \"شکست کوچکی که مثل همیشه‌ها تفسیر می‌شود\", \"برنامه‌ریزی برای آینده\"], \"thoughts\": [\"من نسبت به همه شکست خورده‌ام\", \"این کار هم مثل بقیه خراب شد\", \"من از پس هیچ چیز برنمی‌آیم\"], \"emotions\": [\"ننگ و خجالت\", \"نومیدی\", \"حس بی‌ارزشی و پرهیز از حرف‌زدن دربارهٔ کار\"], \"coping_mode\": \"اجتناب\", \"coping_examples\": [\"فرار از چالش و رقابت\", \"به‌تعویق‌انداختن شروع‌ها\", \"تغییر موضوع وقتی پای موفقیت وسط است\"], \"situations\": [\"مهمانی‌هایی که حرف کار و موفقیت است\", \"جمع خانوادهٔ همسر\", \"شب‌های تصمیم برای آینده\"], \"couple_trigger\": \"سؤال یا تعریف از موفقیت‌های دیگران\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(8, 'interpretation', 'young-schema-full-l3', NULL, 'sch_7', NULL, NULL, 'طرحوارهٔ وابستگی / بی‌کفایتی', '{\"need\": \"نیاز به حمایت در تصمیم‌گیری و احساس کفایت روزمره\", \"sensitivity\": \"مسئولیت‌های جدید زندگی مشترک (مالی، اداری) می‌تواند ترسِ «از عهده برنمی‌آیم» ایجاد کند.\", \"partner_sees\": \"شریک ممکن است بار تصمیم‌ها را یک‌جانبه بکشد و سپس از «تک‌روی» همسر گلایه کند.\", \"resource\": \"توجه به نظر مشورت‌کننده و اهمیت دادن به رأی دیگران\", \"question\": \"کدام تصمیم‌های زندگی مشترک سخت‌ترین‌هاست و چه حمایتی کمک می‌کند؟\", \"activation\": {\"when\": \"وقتی باید تنها تصمیم بگیرد یا کار تازه‌ای را بدون حمایتِ تکیه‌گاه شروع کند.\", \"triggers\": [\"تصمیم‌های بزرگ و مسئولیت تازه\", \"غیبت همسر یا تکیه‌گاه عادی\", \"تعریف دیگران از استقلال و تصمیم‌گیری\", \"پیچیدگی کار و ترس از اشتباه\"], \"thoughts\": [\"از پس‌اش برنمی‌آیم\", \"بدون او گم می‌شوم\", \"تصمیم من قطعاً بد است\"], \"emotions\": [\"اضطراب و درماندگی\", \"ترس از تصمیم غلط\", \"حس بی‌کفایتی\"], \"coping_mode\": \"تسلیم\", \"coping_examples\": [\"واگذاری تصمیم به همسر\", \"درخواست تأیید برای هر قدم\", \"به‌تعویق‌انداختن تا کسی دیگر تصمیم بگیرد\"], \"situations\": [\"خریدهای مهم و قراردادها\", \"تصمیم دربارهٔ کار یا مهاجرت\", \"دوره‌های سفر یا غیبت همسر\"], \"couple_trigger\": \"درخواست تصمیم مستقل، یا ناتوان‌سازی ناخواستهٔ همسر (انجام‌دادن همهٔ کارها به‌جای او)\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(9, 'interpretation', 'young-schema-full-l3', NULL, 'sch_8', NULL, NULL, 'طرحوارهٔ آسیب‌پذیری به ضرر یا بیماری', '{\"need\": \"نیاز به امنیت و پیش‌بینی‌پذیری محیط\", \"sensitivity\": \"ریسک‌های مالی، سفر یا تصمیم‌های بدون برنامه می‌تواند نگرانی فراگیر بسازد.\", \"partner_sees\": \"شریک ممکن است این نگرانی را «ترمز زندگی» یا افراط در احتیاط ببیند.\", \"resource\": \"پیش‌بینی ریسک‌ها و محافظت واقعی از خانواده\", \"question\": \"چه چیزی به شما احساس امنیت می‌دهد و چگونه می‌توانیم آن را در زندگی روزمره فراهم کنیم؟\", \"activation\": {\"when\": \"پیش از تصمیم‌های عادی روزمره که ذهن او بوی «خطر» می‌گیرد — سلامت، پول، امنیت، سفر.\", \"triggers\": [\"یک علامت جسمی کوچک\", \"خبرهای ناگوار\", \"تصمیم مالی یا سفر\", \"تغییر و چیزهای تازه و ناشناخته\"], \"thoughts\": [\"اگر فلان شود چه؟\", \"این کار خطرناک است\", \"نباید ریسک کنیم\"], \"emotions\": [\"اضطراب مزمن و بی‌قراری\", \"هراس موضعی\", \"آسوده‌نشدن حتی بعد از اطمینان\"], \"coping_mode\": \"اجتناب\", \"coping_examples\": [\"انجام‌ندادن کارهای جدید\", \"جست‌وجوی اطمینان مکرر از همسر\", \"کنترل افراطی برنامه‌ها\"], \"situations\": [\"برنامه‌ریزی سفر\", \"انتخاب‌های مالی\", \"سلامت خود و فرزندان\"], \"couple_trigger\": \"پیشنهادهای تازه یا ریسک‌دارِ همسر\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(10, 'interpretation', 'young-schema-full-l3', NULL, 'sch_9', NULL, NULL, 'طرحوارهٔ گرفتاری / خویشتن تحول‌نیافته', '{\"need\": \"نیاز به تأیید خانوادهٔ مبدأ و حفظ پیوند عاطفی\", \"sensitivity\": \"تعارض میان وفاداری به خانوادهٔ مبدأ و نیازهای رابطهٔ زناشویی؛ دخالت خانواده در تصمیم‌ها.\", \"partner_sees\": \"شریک ممکن است احساس کند همیشه در رتبهٔ دوم قرار دارد یا رابطه «سه‌نفره» است.\", \"resource\": \"وفاداری خانوادگی، مسئولیت‌پذیری نسبت به عزیزان\", \"question\": \"در تصمیم‌های مهم، صدا و نظر کدام افراد بیشترین وزن را دارد؟ کجای این تصویر خودِ شماست؟\", \"activation\": {\"when\": \"وقتی نظر، سلیقه یا تصمیمِ مستقلِ او جدا از فردِ دلبسته (مادر یا همسر) مطرح می‌شود.\", \"triggers\": [\"پرسیدن نظر و علایق خودش\", \"مخالفت با فردِ دلبسته\", \"تصمیم بدون مشورت\", \"مسئله‌های مربوط به خانوادهٔ مبدأ\"], \"thoughts\": [\"بدون او نمی‌دانم کی هستم و چه می‌خواهم\", \"اگر مخالفم شوم رابطه به‌هم می‌خورد\", \"نظرِ من چیزی نیست که اهل خانه باشد\"], \"emotions\": [\"اضطراب جدایی\", \"خالی بودنِ هویتی\", \"سرگشتگی در انتخاب\"], \"coping_mode\": \"تسلیم\", \"coping_examples\": [\"هم‌رأی شدن با نظر دیگران\", \"بیان‌نکردن سلیقهٔ خود\", \"ادغام در خواسته‌های خانواده یا همسر\"], \"situations\": [\"بحث‌های «تو خودت چه می‌خواهی؟»\", \"تصمیم‌های مشترک زندگی\", \"تعارض بین خانوادهٔ مبدأ و همسر\"], \"couple_trigger\": \"پرسش از نظر مستقل یا اختلاف نظر با همسر\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(11, 'interpretation', 'young-schema-full-l3', NULL, 'sch_10', NULL, NULL, 'طرحوارهٔ اطاعت / تسلیم', '{\"need\": \"نیاز به احساس امنیت در بیان مخالفت بدون تنبیه\", \"sensitivity\": \"اختلاف‌نظر مستقیم ممکن است با ترس از عواقب همراه شود؛ خشم انباشته به‌صورت غیرمستقیم خارج می‌شود.\", \"partner_sees\": \"شریک ممکن است فکر کند همه‌چیز را قبول می‌کند، اما بعد با قهر، تأخیر یا فراموشی روبه‌رو شود.\", \"resource\": \"انعطاف و توان همکاری و کنار آمدن با دیگران\", \"question\": \"آخرین باری که واقعاً مخالفت کردید چه شد؟ اگر مخالفت «امن» بود چه می‌گفتید؟\", \"activation\": {\"when\": \"وقتی خواسته‌اش برآورده نشود یا قاعده و محدودیتی سر راهش قرار بگیرد.\", \"triggers\": [\"شنیدن «نه»\", \"انتظار نداشتنِ دیگران از او\", \"دیدن امتیاز دیگران\", \"صبر خواستن\"], \"thoughts\": [\"قوانین برای من نیست\", \"من لیاقت بیشتر دارم\", \"او باید بیشتر بدهد\"], \"emotions\": [\"خشم از بی‌عدالتی ادراک‌شده\", \"عصبانیت فوری\", \"تحقیر پنهان محدودیت‌ها\"], \"coping_mode\": \"بیش‌جبرانی\", \"coping_examples\": [\"مطالبهٔ فوری و بی‌تحملی با انتظار\", \"تسلط بر تصمیم‌ها\", \"بی‌اعتبار کردن قاعده‌ها\"], \"situations\": [\"تقسیم کارهای خانه\", \"خرید و هزینه‌ها\", \"موقعیت‌های عمومی که محدودیت می‌سازند\"], \"couple_trigger\": \"ممانعت یا درخواست متقابل از سمت همسر\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(12, 'interpretation', 'young-schema-full-l3', NULL, 'sch_11', NULL, NULL, 'طرحوارهٔ ایثار و فداکاری', '{\"need\": \"نیاز به پاسخ به نیاز دیگران به‌عنوان هویت و ارزش\", \"sensitivity\": \"نیازهای خود پنهان می‌ماند و نارضایتی انباشته ناگهان فوران می‌کند یا به فرسودگی می‌رسد.\", \"partner_sees\": \"شریک ممکن است «همه‌چیز» را دریافت کند اما هرگز نمی‌داند طرف مقابل واقعاً چه می‌خواهد.\", \"resource\": \"سخاوت، مراقبت و توان پرورش دادن رابطه\", \"question\": \"اگر فقط «یک» نیاز خودتان را این هفته بیان کنید، آن نیاز چیست؟\", \"activation\": {\"when\": \"در موقعیت هیجانی یا خسته‌کننده، یا مقابل هر محرکِ لذت فوری که راهِ تخلیهٔ سریع می‌دهد.\", \"triggers\": [\"دعوا و تنش\", \"انتظار و معطل‌ماندن\", \"خستگی و کسالت\", \"وسوسه: خوراک، خرید، صفحه‌نمایش\"], \"thoughts\": [\"الان باید خالی شوم\", \"بعداً فکر می‌کنم\", \"یک بار مهم نیست\"], \"emotions\": [\"خشم لحظه‌ای و بی‌قراری\", \"لذت کوتاه و بعدش پشیمانی و شرم\"], \"coping_mode\": \"تسلیم به تکانه\", \"coping_examples\": [\"انفجار خشم و صدای بالا\", \"خرج‌های ضربدری یا پرخوری\", \"ترک کارها نیمه‌کاره\"], \"situations\": [\"دعواهای زناشویی\", \"شب‌های خسته و کسل\", \"فشارهای پایان‌هفته و تعطیلی‌ها\"], \"couple_trigger\": \"تأخیر در برآورده‌شدن خواسته یا بالا گرفتن بحث\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(13, 'interpretation', 'young-schema-full-l3', NULL, 'sch_12', NULL, NULL, 'طرحوارهٔ پذیرش‌جویی / جلب توجه', '{\"need\": \"نیاز به تأیید و توجه بیرونی\", \"sensitivity\": \"واکنش به قضاوت دیگران دربارهٔ رابطه (خانواده، دوستان) ممکن است بر نیازهای واقعی زوج غلبه کند.\", \"partner_sees\": \"شریک ممکن است احساس کند زندگی مشترک برای «نمایش دیگران» اداره می‌شود.\", \"resource\": \"توجه به ظاهر روابط و مهارت‌های اجتماعی\", \"question\": \"اگر هیچ‌کس این تصمیم را نمی‌دید، شما چه می‌کردید؟\", \"activation\": {\"when\": \"در تعامل با فردِ قدرتمند یا کنترل‌گر — برای جلوگیری از خشم، طرد یا جنگِ تمام‌عیار.\", \"triggers\": [\"لحن قاطع یا دستوری همسر\", \"نظم‌دادن و انتظارات خانواده\", \"موقعیت‌های عمومی که «صحنه را نمی‌شود ترک کرد»\"], \"thoughts\": [\"حرف نزنم تا دعوا نشود\", \"مهم نیست، هر چه تو بگویی\", \"نظر من چیزی عوض نمی‌کند\"], \"emotions\": [\"خشم فروخورده\", \"کلافگی و بی‌حسی تدریجی\", \"انفجارهای تأخیری و بی‌تناسب\"], \"coping_mode\": \"تسلیم\", \"coping_examples\": [\"اطاعت ظاهری و بیانیِ نظر\", \"پرهیز از مخالفت\", \"خروجی درازمدت: دوری عاطفی و سردی\"], \"situations\": [\"جلسات تصمیم خانواده\", \"برنامه‌های همسر که بدون مشورت چیده می‌شود\", \"وقتی جلوی بقیه است و نمی‌شود حرف زد\"], \"couple_trigger\": \"کنترل یا اطمینان‌خواهی مکرر از سمت همسر\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(14, 'interpretation', 'young-schema-full-l3', NULL, 'sch_13', NULL, NULL, 'طرحوارهٔ منفی‌گرایی / بدبینی', '{\"need\": \"نیاز به ثبات و اجتناب از درد و ناکامی تکرارشونده\", \"sensitivity\": \"بهینه‌بینی شریک ممکن است «سطحی بودن» تعبیر شود؛ شکایت‌های مکرر فرسایشی می‌شود.\", \"partner_sees\": \"شریک ممکن است احساس کند هیچ برنامه‌ای هرگز کافی یا خوب نیست.\", \"resource\": \"دقت، پیش‌بینی مشکلات واقعی و واقع‌گرایی\", \"question\": \"وقتی مشکل مطرح می‌شود، اول به چه چیزی فکر می‌کنید؟ چه چیزی به شما ثابت می‌کند «خوب» شد؟\", \"activation\": {\"when\": \"وقتی نیاز خودش با نیاز دیگری رقابت می‌کند — حتی رقابتِ خیالی و بی‌درخواستیِ طرف.\", \"triggers\": [\"خستگی یا غم‌ناکی اطرافیان\", \"هر درخواستِ کوچک\", \"حس گناهِ «من بهترم»\", \"نیاز بیان‌نشدهٔ همسر\"], \"thoughts\": [\"اگر به فکر خودم باشم خودخواه هستم\", \"باید همه را راضی نگه دارم\", \"حالِ بقیه مهم‌تر است\"], \"emotions\": [\"خستگی مزمن\", \"دلخوری پنهان (کسی حال من را نمی‌پرسد)\", \"حس گناه هنگام گفتنِ نه\"], \"coping_mode\": \"تسلیم\", \"coping_examples\": [\"فداکاری بیش از حد و خودکار\", \"درخواست‌نکردن و پنهان‌کردن نیاز خود\", \"مراقبت از همه به‌جز خود\"], \"situations\": [\"مهمانی‌داری و پذیرایی\", \"مراقبت از بزرگ‌ترها و بچه‌ها\", \"تعطیلاتی که همه برای «دیگران» برنامه می‌شود\"], \"couple_trigger\": \"نیاز بیان‌نشده یا درخواست متقابل همسر\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(15, 'interpretation', 'young-schema-full-l3', NULL, 'sch_14', NULL, NULL, 'طرحوارهٔ بازداری هیجانی', '{\"need\": \"نیاز به امنیت در ابراز احساسات بدون از دست دادن کنترل\", \"sensitivity\": \"لحظه‌های صمیمیت هیجانی، گریه یا خشم سرکوب می‌شود؛ شریک «دیوار» را تجربه می‌کند.\", \"partner_sees\": \"شریک ممکن است سردی، بی‌تفاوتی یا بی‌اعتمادی به اشتراک هیجانی برداشت کند.\", \"resource\": \"خویشتن‌داری در بحران و ثبات هیجانی\", \"question\": \"وقتی احساس قوی می‌آید، در بدنتان چه می‌کنید؟ کوچک‌ترین ابراز امنِ ممکن چیست؟\", \"activation\": {\"when\": \"وقتی دیده شدن و تحسین شدن در محک است — جمع‌ها، موفقیت‌ها، شبکه‌های اجتماعی.\", \"triggers\": [\"مقایسه با دیگران\", \"بی‌اعتنایی نسبی جمع\", \"موفقیت یا تعریفِ دیگران\", \"انتشار چیزی در فضای مجازی\"], \"thoughts\": [\"الان چه فکری درباره‌ام می‌کنند؟\", \"باید بهترین باشم که دیده شوم\", \"تعریف نکردن یعنی کم‌ارزش بودن\"], \"emotions\": [\"اضطراب عملکرد\", \"خالی بودن بعد از تحسین\", \"حسادت و رقابت\"], \"coping_mode\": \"بیش‌جبرانی\", \"coping_examples\": [\"جلوه‌گری و کارِ بیشتر برای دیده شدن\", \"گزارش‌دادن موفقیت‌ها\", \"یا اجتناب: نرفتن به جمع‌های ارزیاب\"], \"situations\": [\"مهمانی‌ها و جمع‌های جدید\", \"بعد از موفقیت همسر یا دیگری\", \"زمان‌های پرگردش در اینستاگرام\"], \"couple_trigger\": \"تحسین‌نکردن یا تعریف همسر از دیگری\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(16, 'interpretation', 'young-schema-full-l3', NULL, 'sch_15', NULL, NULL, 'طرحوارهٔ معیارهای سرسختانه', '{\"need\": \"نیاز به احساس کفایت از طریق درستی و کار مطلق\", \"sensitivity\": \"معیارهای بالا برای نظم، پول، کار یا تربیت فرزند؛ خطاهای شریک «تنبلی یا بی‌دقتی» دیده می‌شود.\", \"partner_sees\": \"شریک ممکن است احساس کند هیچ‌وقت به اندازهٔ کافی خوب نیست و دائماً در حال ممیزی است.\", \"resource\": \"کیفیت‌محوری، پشتکار و پیشبرد اهداف مشترک\", \"question\": \"در خانهٔ شما «درست انجام دادن» یعنی چه؟ اگر ۸۰٪ هم انجام شود چه می‌شود؟\", \"activation\": {\"when\": \"وقتی آینده پیش‌بینی می‌شود یا اتفاقی مبهم رخ می‌دهد؛ و به‌خصوص بعد از خبرهای خوب یا تجربه‌های شیرین.\", \"triggers\": [\"برنامه‌های جدید\", \"خبرها و اتفاق‌های مبهم\", \"رفتار مبهم همسر\", \"لحظه‌های خوب و بی‌دردسر\"], \"thoughts\": [\"آخرش خراب می‌شود\", \"حالا که خوب است، فردا بد می‌شود\", \"حتماً دنبال آچار است\"], \"emotions\": [\"نگرانی مزمن\", \"ناامیدی پیشگیرانه\", \"لذت‌ناپذیری (نمی‌تواند شاد باشد که بعداً افسرده نشود)\"], \"coping_mode\": \"تسلیم\", \"coping_examples\": [\"انتظار بدترین را کشیدن\", \"شکایت مزمن و دیدن عیب‌ها\", \"خنثی‌کردن خبرهای خوب با «ولی»\"], \"situations\": [\"شب قبل از رویدادهای مهم\", \"برنامه‌ریزی سفر\", \"درست بعد از اتفاق‌های خوب\"], \"couple_trigger\": \"پیشنهادهای خوش‌بینانهٔ همسر یا اتفاق خوبِ ناگهانی\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(17, 'interpretation', 'young-schema-full-l3', NULL, 'sch_16', NULL, NULL, 'طرحوارهٔ استحقاق / بزرگ‌منشی', '{\"need\": \"نیاز به حفظ احساس برتری یا کنترل برای پرهیز از تحقیر و محدودیت\", \"sensitivity\": \"محدود کردن یا «نه» شنیدن ممکن است با خشم یا تحقیر پاسخ داده شود؛ قواعد مشترک سخت برقرار می‌شود.\", \"partner_sees\": \"شریک ممکن است احساس کند نظرش و نیازهایش همیشه ثانویه است.\", \"resource\": \"اعتمادبه‌نفس، رهبری و توان تصمیم در بحران\", \"question\": \"وقتی «نه» می‌شنوید چه حسی می‌آید و چه اتفاقی می‌افتد؟\", \"activation\": {\"when\": \"وقتی هیجان (خشم، غم، حتی محبت و بذله‌گویی) بالا می‌رود و او تصمیم می‌گیرد «بیرون نریزد».\", \"triggers\": [\"موقعیت‌های عاطفی پرشدت\", \"تعارض و دعوا\", \"بودن جلوی دیگران\", \"تربیت خانوادگیِ «جیغ‌زدن و گریه ممنوع»\"], \"thoughts\": [\"هیجان نشانهٔ ضعف است\", \"نباید به رویشان بیاورم\", \"کنترل کن؛ بعداً وقتش نیست\"], \"emotions\": [\"آشفتگی پنهان زیر چهرهٔ خنثی\", \"فاصلهٔ عاطفی و سردیِ دیده‌شده\", \"تنش جسمیِ نگه‌داشتن\"], \"coping_mode\": \"اجتناب\", \"coping_examples\": [\"سرکوب و تغییر موضوع\", \"منطقی‌کردن همه‌چیز\", \"ترک موقعیت عاطفی یا خاموش شدن\"], \"situations\": [\"بحث‌های عاطفی زناشویی\", \"گریه یا ابراز شدید همسر\", \"ابراز محبت جلوی دیگران\"], \"couple_trigger\": \"درخواست ابراز احساس از سمت همسر\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(18, 'interpretation', 'young-schema-full-l3', NULL, 'sch_17', NULL, NULL, 'طرحوارهٔ خویشتن‌داری ناکافی', '{\"need\": \"نیاز به مهار تکانه و تحمل ناکامی بدون انفجار یا فرار\", \"sensitivity\": \"تعارض‌ها ناگهانی داغ می‌شوند؛ تصمیم‌های شتاب‌زده (خرید، ترک گفت‌وگو، مصرف) رابطه را می‌لرزاند.\", \"partner_sees\": \"شریک ممکن است نقش «والدِ مهارکننده» بگیرد و خسته شود.\", \"resource\": \"خودانگیختگی، شوخ‌طبعی و هیجان در رابطه\", \"question\": \"از «جرقه تا انفجار\\/فرار» چند ثانیه فاصله هست؟ در آن فاصله چه چیزی می‌تواند کمکتان کند؟\", \"activation\": {\"when\": \"هر کاری در آستانهٔ «تحویل» است و معیار درونی هنوز راضی نیست — حتی برای کارهای نامهم.\", \"triggers\": [\"بازبینی کار خود یا دیگران\", \"قضاوت‌شدنی بودن نتیجه\", \"بی‌نظمی و شلخی\", \"استاندارد متفاوتِ همسر\"], \"thoughts\": [\"هنوز کافی نیست\", \"باید بی‌نقص باشد\", \"اگر درست انجام نمی‌شود، خودم می‌کنم\"], \"emotions\": [\"تنش مزمن و بی‌حوصلگی\", \"نارضایتی دائمی\", \"وقت‌نرم برای لذت و استراحت نداشتن\"], \"coping_mode\": \"بیش‌جبرانی\", \"coping_examples\": [\"سخت‌گیری مضاعف و کارِ بیشتر\", \"بازبینی‌های تکراری\", \"انتقال استاندارد به اطرافیان (توقّع زیاد از همسر و فرزند)\"], \"situations\": [\"مهمانی‌دادن و پذیرایی\", \"کارهای خانه و پروژه‌ها\", \"نمره‌ها و عملکرد فرزندان\"], \"couple_trigger\": \"متفاوت بودن معیارِ همسر\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(19, 'interpretation', 'young-schema-full-l3', NULL, 'sch_18', NULL, NULL, 'طرحوارهٔ تنبیه‌گرایی و بی‌رحمی', '{\"need\": \"نیاز به پذیرش خطاپذیری انسانی بدون مجازات\", \"sensitivity\": \"اشتباه شریک با مجازات (قهر طولانی، تحریم عاطفی، سرزنش داوری‌گونه) پاسخ داده می‌شود.\", \"partner_sees\": \"شریک ممکن است یاد بگیرد اشتباهات را پنهان کند؛ صمیمیت و صداقت آسیب می‌بیند.\", \"resource\": \"انضباط، مسئولیت‌پذیری و پایبندی به اصول\", \"question\": \"در خانوادهٔ شما برای اشتباه چه بلایی می‌آمد؟ اینجا چه می‌خواهید اتفاق بیفتد؟\", \"activation\": {\"when\": \"وقتی کسی — خودش یا دیگران — «مرتکب خطا» می‌شود یا قاعده‌ای را می‌شکند.\", \"triggers\": [\"اشتباه فرزند یا همسر\", \"بی‌قیدی و قانون‌شکنی دیگران\", \"خطای خودش (خودتنبیهی)\", \"بی‌انصافی‌های ادراک‌شده\"], \"thoughts\": [\"باید جریمه شود\", \"بی‌قیدی نباید بی‌پاسخ بماند\", \"من حق دارم سخت بگیرم\"], \"emotions\": [\"خشم اخلاقی\", \"سردیِ تنبیهی و قطع محبت به‌عنوان مجازات\", \"بی‌رحمی لحظه‌ای (پشیمانیِ بعدی کم است)\"], \"coping_mode\": \"بیش‌جبرانی\", \"coping_examples\": [\"مجازات و قهرِ تنبیهی\", \"سخت‌گیری و انتقام‌گیری کوچک\", \"خودتنبیهی شدید هنگام خطا\"], \"situations\": [\"تربیت فرزند\", \"بعد از خطاهای همسر\", \"شکست و اشتباه خودش\"], \"couple_trigger\": \"خطا یا بی‌قیدیِ ادراک‌شده از سمت همسر\"}}', 'high', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:03:33'),
(20, 'cycle', 'young-schema-full-l3', NULL, 'sch_2', NULL, 'sch_1', 'چرخهٔ تعقیب – فاصله‌گیری', '{\"trigger\":\"یک موقعیت عادی مثل پاسخ ندادن به تماس، دیر رسیدن یا خسته بودن در پایان روز.\",\"steps\":[{\"actor\":\"A\",\"kind\":\"perception\",\"text\":\"نبودِ پاسخ را نشانهٔ سرد شدن رابطه می‌خواند.\"},{\"actor\":\"A\",\"kind\":\"reaction\",\"text\":\"پیگیری مکرر، تماس پشت تماس، سؤال‌های تأییدجویانه.\"},{\"actor\":\"B\",\"kind\":\"perception\",\"text\":\"فشار را طلب‌کاری عاطفی و فضای خفگی تجربه می‌کند.\"},{\"actor\":\"B\",\"kind\":\"reaction\",\"text\":\"فاصله می‌گیرد، کوتاه جواب می‌دهد یا گفت‌وگو را به تعویق می‌اندازد.\"}],\"escalation\":\"هر فاصله‌گیری، ترسِ رهاشدگی طرف اول را تأیید و پیگیری را بیشتر می‌کند؛ هر پیگیری، نیاز به آرامش طرف دوم را فرو می‌ریزد و فاصله را عمیق‌تر — حلقهٔ خودتقویت‌شونده.\",\"alternative\":\"این الگو ممکن است صرفاً تفاوت سبک آرام‌گیری (نیاز به تنهایی در برابر نیاز به اتصال) باشد، نه طرحوارهٔ فعال؛ خستگی شغلی یا الگوی خانوادهٔ مبدأ هم توضیح‌های جایگزین‌اند.\",\"min_level\":\"moderate\"}', 'medium', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(21, 'cycle', 'young-schema-full-l3', NULL, 'sch_15', NULL, 'sch_5', 'چرخهٔ ممیزی – دفاع شرم', '{\"trigger\":\"خطای کوچک: ظرف نشسته، خرج اشتباه، تأخیر در کاری.\",\"steps\":[{\"actor\":\"A\",\"kind\":\"perception\",\"text\":\"معیارِ بر هم خورده را می‌بیند.\"},{\"actor\":\"A\",\"kind\":\"reaction\",\"text\":\"تذکر اصلاحی با لحن عیب‌جویانه یا سؤال بازخواستی.\"},{\"actor\":\"B\",\"kind\":\"perception\",\"text\":\"تذکر را حکم «من به‌دردنمی‌خورم» می‌شنود.\"},{\"actor\":\"B\",\"kind\":\"reaction\",\"text\":\"یا دفاع آتشین و مقابلِ‌هم قرار گرفتن، یا سکوت و کنار کشیدن.\"}],\"escalation\":\"هر تذکرِ بیشتر، شرم را عمیق‌تر و دفاع را سنگین‌تر می‌کند؛ موضوع کوچک به «احترام و ارزشمندی» گره می‌خورد.\",\"alternative\":\"تکرار یک بی‌دقتی واقعی می‌تواند بار عملی مشروع برای گفت‌وگو داشته باشد؛ لحن و فرمِ گفت‌وگو موضوع اصلی است نه محتوا.\",\"min_level\":\"moderate\"}', 'medium', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(22, 'cycle', 'young-schema-full-l3', NULL, 'sch_3', NULL, 'sch_14', 'چرخهٔ بازجویی – دیوار سکوت', '{\"trigger\":\"سؤال ساده دربارهٔ برنامه یا یک اطلاعات جدید دربارهٔ گذشته.\",\"steps\":[{\"actor\":\"A\",\"kind\":\"perception\",\"text\":\"نبودِ شفافیت را نشانهٔ پنهان‌کاری می‌خواند.\"},{\"actor\":\"A\",\"kind\":\"reaction\",\"text\":\"سؤال‌های پشت‌سرهم و بررسی جزئیات.\"},{\"actor\":\"B\",\"kind\":\"perception\",\"text\":\"پرسش‌ها را ورود به حریم و پیش‌داوری می‌بیند.\"},{\"actor\":\"B\",\"kind\":\"reaction\",\"text\":\"کوتاه پاسخ می‌دهد، موضوع را عوض می‌کند یا می‌گوید «مهم نیست».\"}],\"escalation\":\"کوتاه‌جوابی، بی‌اعتمادی را قوی‌تر و سؤال‌ها را تیزتر می‌کند؛ اطلاعات واقعی ردوبدل نمی‌شود و شک رشد می‌کند.\",\"alternative\":\"تفاوت فرهنگی\\/خانوادگی دربارهٔ میزان اشتراک‌گذاری جزئیات زندگی می‌تواند توضیح بخشی از الگو باشد.\",\"min_level\":\"moderate\"}', 'medium', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(23, 'cycle', 'young-schema-full-l3', NULL, 'sch_16', NULL, 'sch_10', 'چرخهٔ سلطه – تسلیم انفجاری', '{\"trigger\":\"تصمیم‌های روزمره: تعطیلات، خرید، برنامهٔ آخر هفته.\",\"steps\":[{\"actor\":\"A\",\"kind\":\"perception\",\"text\":\"راه‌حل خودش را درست‌ترین می‌بیند.\"},{\"actor\":\"A\",\"kind\":\"reaction\",\"text\":\"تصمیم می‌گیرد و انتظار همراهی دارد.\"},{\"actor\":\"B\",\"kind\":\"perception\",\"text\":\"برای حفظ آرامش تسلیم می‌شود.\"},{\"actor\":\"B\",\"kind\":\"reaction\",\"text\":\"رضایت ظاهری اما همراه با قهر، تأخیر یا بی‌میلی غیرمستقیم.\"}],\"escalation\":\"تسلیم‌های تکراری خشم انباشته می‌سازد که سرانجام به‌صورت انفجار یا سردی طولانی آزاد می‌شود؛ طرف اول سرگردان می‌ماند که «مگر چه کردم؟»\",\"alternative\":\"گاهی یک نفر واقعاً در حوزه‌ای تخصص بیشتری دارد و تقسیم نقش منطقی است؛ ملاک، تکرار یک‌طرفه بودن و احساس دیده‌نشدن است.\",\"min_level\":\"moderate\"}', 'medium', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(24, 'cycle', 'young-schema-full-l3', NULL, 'sch_18', NULL, 'sch_11', 'چرخهٔ داوری – فداکاری بدهکار', '{\"trigger\":\"خطای یکی از دو طرف یا نیازِ بیان‌نشده.\",\"steps\":[{\"actor\":\"A\",\"kind\":\"perception\",\"text\":\"خطا را تخلف اخلاقی می‌بیند و مستحق واکنش می‌داند.\"},{\"actor\":\"A\",\"kind\":\"reaction\",\"text\":\"سرزنش داوری‌گونه یا تحریم عاطفی.\"},{\"actor\":\"B\",\"kind\":\"perception\",\"text\":\"برای جبران، بیش از پیش مسئول می‌شود و «بدهی» حس می‌کند.\"},{\"actor\":\"B\",\"kind\":\"reaction\",\"text\":\"فداکاریِ بیشتر همراه با گلایهٔ انباشته: «ببین چقدر برایت گذاشته‌ام».\"}],\"escalation\":\"هر سرزنش فداکاری را بیشتر و هر فداکاری، حساب عاطفی را سنگین‌تر می‌کند؛ هیچ‌کس نیاز واقعی‌اش را نمی‌گوید.\",\"alternative\":\"فداکاری می‌تواند نشانهٔ واقعی عشق هم باشد؛ ملاک، همراه بودن با گلایهٔ انباشته و انتظار جبران است.\",\"min_level\":\"moderate\"}', 'medium', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(25, 'cycle', 'young-schema-full-l3', NULL, 'sch_8', NULL, 'sch_17', 'چرخهٔ ترمز – گاز', '{\"trigger\":\"تصمیم‌های ریسک‌دار: سرمایه‌گذاری، تغییر شغل، سفر.\",\"steps\":[{\"actor\":\"A\",\"kind\":\"perception\",\"text\":\"خطر را بزرگ و نزدیک می‌بیند.\"},{\"actor\":\"A\",\"kind\":\"reaction\",\"text\":\"مخالفت، لیست ریسک‌ها، تعویق تصمیم.\"},{\"actor\":\"B\",\"kind\":\"perception\",\"text\":\"احتیاط را خفه‌کننده و سخت‌گیری بی‌دلیل می‌بیند.\"},{\"actor\":\"B\",\"kind\":\"reaction\",\"text\":\"تصمیم تکی یا رفتار تکانشی مقابل چشم طرف مقابل.\"}],\"escalation\":\"مخالفت بیشتر، تحریک را زیاد و رفتار تکانشی، ترس را عمیق‌تر می‌کند؛ اعتماد تصمیم‌گیری مشترک فرسوده می‌شود.\",\"alternative\":\"اختلاف در آستانهٔ ریسک‌پذیری طبیعی و حتی مکمل است؛ مشکل، سبکِ حل تعارض است نه وجود تفاوت.\",\"min_level\":\"moderate\"}', 'medium', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema Therapy: A Practitioner\'s Guide. Guilford Press.', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(26, 'cross_relation', 'young-schema-full-l3', NULL, 'sch_2', 'attachment-style', 'attachment_anxiety', 'هم‌پوشانی مفهومی رهاشدگی (YSQ) و اضطراب دلبستگی (ECR-R)', '{\"text\":\"طرحوارهٔ رهاشدگی و اضطراب دلبستگی دو چارچوب متفاوت برای توصیف یک حساسیت مشترک‌اند: ترس از طرد و جدایی. فعال بودن هم‌زمان این دو در یک نفر (حتی از دو آزمون متفاوت)، احتمال حساسیت بالای این فرد به نشانه‌های فاصله را تقویت می‌کند؛ اما این ادغام، فرضیهٔ بالینی است و عدد دو آزمون با هم جمع یا مقایسه نمی‌شود.\",\"note\":\"برای بررسی: تاریخچهٔ جدایی‌ها، واکنش به تأخیر پاسخ، و میزان نیاز به اطمینان‌بخشی روزانه.\"}', 'medium', 'Young et al. (2003)؛ Fraley, Waller & Brennan (2000) — هم‌پوشانی مفهومی، نه هم‌ارزی روان‌سنجی', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(27, 'cross_relation', 'young-schema-full-l3', NULL, 'sch_14', 'attachment-style', 'attachment_avoidance', 'هم‌پوشانی مفهومی بازداری هیجانی (YSQ) و اجتناب دلبستگی (ECR-R)', '{\"text\":\"بازداری هیجانی و اجتناب دلبستگی هر دو «کاهش ابراز هیجان و نزدیکی» را توصیف می‌کنند. فعال بودن هم‌زمان آن‌ها در یک نفر می‌تواند به معنای اتکای بالا به خودکفایی هیجانی باشد که شریک آن را «دیوار» تجربه می‌کند؛ این یک فرضیهٔ قابل بررسی است.\",\"note\":\"برای بررسی: آخرین باری که فرد در رابطه «قابل‌تردید» آسیب‌پذیر شده چه موقعیتی بود؟\"}', 'medium', 'Young et al. (2003)؛ Fraley, Waller & Brennan (2000) — هم‌پوشانی مفهومی، نه هم‌ارزی روان‌سنجی', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(28, 'pattern', 'attachment-style', NULL, NULL, NULL, NULL, 'الگوی دلواپس – اجتنابی (الف دلواپس / ب اجتنابی)', '{\"name\":\"تعقیب – فاصله (دلواپس\\/اجتنابی)\",\"conditions\":[{\"dim\":\"attachment_anxiety\",\"severity_in\":[\"severe\"],\"side\":\"A\"},{\"dim\":\"attachment_avoidance\",\"severity_in\":[\"severe\"],\"side\":\"B\"}],\"text\":\"اضطراب دلبستگی بالا در فرد الف و اجتناب بالا در فرد ب، رایج‌ترین بستر چرخهٔ «تعقیب – فاصله‌گیری» است: هرچه اولی نزدیک‌تر می‌خواهد، دومی بیشتر عقب می‌کشد و هرچه دومی عقب می‌کشد، اولی وحشت‌زده‌تر تعقیب می‌کند. این فرضیه است، نه تشخیص؛ همان الگو می‌تواند ریشه در تجربه‌های فعلی رابطه داشته باشد.\"}', 'high', 'Fraley, Waller & Brennan (2000)؛ ادبیات دلبستگی بزرگسالی', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(29, 'pattern', 'attachment-style', NULL, NULL, NULL, NULL, 'الگوی دلواپس – اجتنابی (الف اجتنابی / ب دلواپس)', '{\"name\":\"تعقیب – فاصله (اجتنابی\\/دلواپس)\",\"conditions\":[{\"dim\":\"attachment_anxiety\",\"severity_in\":[\"severe\"],\"side\":\"B\"},{\"dim\":\"attachment_avoidance\",\"severity_in\":[\"severe\"],\"side\":\"A\"}],\"text\":\"اضطراب دلبستگی بالا در فرد ب و اجتناب بالا در فرد الف، بستر چرخهٔ «تعقیب – فاصله‌گیری» است: هرچه فرد ب نزدیک‌تر می‌خواهد، فرد الف بیشتر عقب می‌کشد و هرچه فرد الف عقب می‌کشد، فرد ب وحشت‌زده‌تر تعقیب می‌کند. این فرضیه است، نه تشخیص.\"}', 'high', 'Fraley, Waller & Brennan (2000)؛ ادبیات دلبستگی بزرگسالی', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(30, 'pattern', 'attachment-style', NULL, NULL, NULL, NULL, 'الگوی دلواپس – دلواپس', '{\"name\":\"دلواپس – دلواپس\",\"conditions\":[{\"dim\":\"attachment_anxiety\",\"severity_in\":[\"severe\"],\"on\":\"both\"}],\"text\":\"اضطراب دلبستگی بالا در هر دو نفر می‌تواند به چرخه‌های «تأییدجویی متقابل – فرسودگی» بینجامد: هر دو به دنبال نشانهٔ اطمینان‌اند و هیچ‌کدام منبع آرامش نمی‌شوند. جنگ‌های سریع و آشتی‌های سریع رایج است.\"}', 'medium', 'Fraley, Waller & Brennan (2000)؛ ادبیات دلبستگی بزرگسالی', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(31, 'pattern', 'attachment-style', NULL, NULL, NULL, NULL, 'الگوی اجتنابی – اجتنابی', '{\"name\":\"اجتنابی – اجتنابی\",\"conditions\":[{\"dim\":\"attachment_avoidance\",\"severity_in\":[\"severe\"],\"on\":\"both\"}],\"text\":\"اجتناب بالا در هر دو نفر معمولاً «آرایش ظاهری» می‌سازد: تعارض آشکار کم است اما صمیمیت و اشتراک هیجانی کم‌عمق می‌ماند؛ مشکلات با سکوت مدیریت می‌شوند نه با گفت‌وگو.\"}', 'medium', 'Fraley, Waller & Brennan (2000)؛ ادبیات دلبستگی بزرگسالی', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(32, 'pattern', 'attachment-style', NULL, NULL, NULL, NULL, 'الگوی امن (منبع قدرت)', '{\"name\":\"دلبستگی امن در هر دو نفر\",\"conditions\":[{\"dim\":\"attachment_anxiety\",\"severity_not_in\":[\"severe\"],\"on\":\"both\"},{\"dim\":\"attachment_avoidance\",\"severity_not_in\":[\"severe\"],\"on\":\"both\"}],\"text\":\"سطح زیر نقطهٔ برش در هر دو بعد دلبستگی برای هر دو نفر، ظرفیت خوبی برای گفت‌وگوی هیجانی، ترمیم تعارض و حمایت متقابل نشان می‌دهد — منبع قدرت قابل اتکا در کار درمانی. (این یافته به‌تنهایی سلامت کل رابطه را اثبات نمی‌کند.)\"}', 'high', 'Fraley, Waller & Brennan (2000)؛ ادبیات دلبستگی بزرگسالی', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(33, 'pattern', 'csi-32-full', NULL, NULL, NULL, NULL, 'CSI: نارضایتی هر دو نفر (زیر نقطهٔ برش)', '{\"name\":\"نارضایتی مشترک\",\"conditions\":[{\"dim\":\"csi_satisfaction\",\"pct_max\":64.7999999999999971578290569595992565155029296875,\"on\":\"both\"}],\"text\":\"نمرهٔ هر دو نفر زیر نقطهٔ برش بالینی (۱۰۴.۵) است: هر دو از رابطه ناراضی‌اند. این هم‌رأیی، مسئله را «مشترک» می‌کند و انگیزهٔ کار مشترک را سنجش‌پذیر می‌سازد؛ به نفع هیچ‌کس نیست که نارضایتی دیگری به‌عنوان «شخصیت او» تفسیر شود.\"}', 'high', 'Funk & Rogge (2007) — نقطهٔ برش بالینی ۱۰۴.۵ (معادل ≈ ۶۴.۹٪ بازهٔ ۰–۱۶۱ سامانه)', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(34, 'pattern', 'csi-32-full', NULL, NULL, NULL, NULL, 'CSI: شکاف ادراک (الف زیر برش / ب بالای برش)', '{\"name\":\"شکاف ادراک کیفیت رابطه\",\"conditions\":[{\"dim\":\"csi_satisfaction\",\"pct_max\":64.7999999999999971578290569595992565155029296875,\"side\":\"A\"},{\"dim\":\"csi_satisfaction\",\"pct_min\":64.900000000000005684341886080801486968994140625,\"side\":\"B\"}],\"text\":\"فرد الف زیر نقطهٔ برش بالینی و فرد ب بالای آن است: دو ادراک متفاوت از یک رابطه. برای الف مشکلات جدی و برای ب وضعیت قابل‌تحمل است؛ همین شکاف خودش موضوع مهم بالینی است و نباید به نفع «راضی‌تر» تفسیر شود.\"}', 'high', 'Funk & Rogge (2007) — نقطهٔ برش بالینی ۱۰۴.۵ (معادل ≈ ۶۴.۹٪ بازهٔ ۰–۱۶۱ سامانه)', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(35, 'pattern', 'csi-32-full', NULL, NULL, NULL, NULL, 'CSI: شکاف ادراک (ب زیر برش / الف بالای برش)', '{\"name\":\"شکاف ادراک کیفیت رابطه\",\"conditions\":[{\"dim\":\"csi_satisfaction\",\"pct_max\":64.7999999999999971578290569595992565155029296875,\"side\":\"B\"},{\"dim\":\"csi_satisfaction\",\"pct_min\":64.900000000000005684341886080801486968994140625,\"side\":\"A\"}],\"text\":\"فرد ب زیر نقطهٔ برش بالینی و فرد الف بالای آن است: دو ادراک متفاوت از یک رابطه. برای ب مشکلات جدی و برای الف وضعیت قابل‌تحمل است؛ همین شکاف خودش موضوع مهم بالینی است و نباید به نفع «راضی‌تر» تفسیر شود.\"}', 'high', 'Funk & Rogge (2007) — نقطهٔ برش بالینی ۱۰۴.۵ (معادل ≈ ۶۴.۹٪ بازهٔ ۰–۱۶۱ سامانه)', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(36, 'pattern', 'csi-32-full', NULL, NULL, NULL, NULL, 'CSI: رضایت هر دو نفر (بالای نقطهٔ برش)', '{\"name\":\"رضایت مشترک — پایهٔ کار\",\"conditions\":[{\"dim\":\"csi_satisfaction\",\"pct_min\":64.900000000000005684341886080801486968994140625,\"on\":\"both\"}],\"text\":\"نمرهٔ هر دو نفر بالای نقطهٔ برش است: پایهٔ رضایت مشترکی وجود دارد که می‌توان کار روی طرحواره‌ها را روی آن بنا کرد. حضور طرحواره‌های فعال در آزمون شخصیت، رضایت فعلی را نقض نمی‌کند؛ یعنی رابطه فعلاً منبع امنی است که کار دشوار طرحواره‌ای می‌تواند در پناه آن انجام شود.\"}', 'high', 'Funk & Rogge (2007) — نقطهٔ برش بالینی ۱۰۴.۵ (معادل ≈ ۶۴.۹٪ بازهٔ ۰–۱۶۱ سامانه)', 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(37, 'recommendation', NULL, NULL, NULL, NULL, NULL, 'توصیهٔ کاربردی', '{\"text\":\"آموزش «چرخهٔ مشترک» به‌عنوان دشمن مشترک به‌جای مقصر: جلسهٔ روان‌آموزشی دربارهٔ ساختار چرخه‌های عاطفی، پیش از هر مداخلهٔ محتوایی.\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(38, 'recommendation', NULL, NULL, NULL, NULL, NULL, 'توصیهٔ کاربردی', '{\"text\":\"شناسایی «لحظهٔ جرقه» و تدوین سیگنال توقف توافقی برای توقف چرخه بین جلسات.\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(39, 'recommendation', NULL, NULL, NULL, NULL, NULL, 'توصیهٔ کاربردی', '{\"text\":\"تمرین ابراز نیاز با فرمول «موقعیت – احساس – نیاز – درخواست کوچک»؛ تمرین ابتدا در جلسه، سپس در خانه.\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(40, 'recommendation', NULL, NULL, NULL, NULL, NULL, 'توصیهٔ کاربردی', '{\"text\":\"برای طرحواره‌ها\\/ابعاد با سطح شدت بالا در هر فرد، ارزیابی فردی جداگانه پیش از ادامهٔ کار زوجی عمیق در نظر گرفته شود.\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(41, 'recommendation', NULL, NULL, NULL, NULL, NULL, 'توصیهٔ کاربردی', '{\"text\":\"در صورت طرح هرگونه موضوع خشونت، ترس یا کنترل در جلسات، غربالگری ایمنی اختصاصی انجام شود؛ آزمون‌های خودگزارشی ملاک تصمیم دربارهٔ ایمنی نیستند.\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(42, 'recommendation', 'young-schema-full-l3', NULL, NULL, NULL, NULL, 'توصیهٔ کاربردی', '{\"text\":\"برای طرحواره‌های «بسیار شدید» YSQ، بازآموزی شناختی و تجربهٔ هیجانی محدود و برنامه‌ریزی‌شده (فلاش‌کارت، دیالوگ طرحواره‌ای) پیش از کار زوجی مستقیم مفید ارزیابی می‌شود؛ تصمیم نهایی با درمانگر است.\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(43, 'recommendation', 'attachment-style', NULL, NULL, NULL, NULL, 'توصیهٔ کاربردی', '{\"text\":\"برای چرخهٔ تعقیب–فاصله، تمرین‌های «زمان‌بندی اتصال» (زمان مشخص تماس\\/پیام) و «پنجرهٔ آرامش» (زمان مشخص تنهایی بدون معنای طرد) به‌عنوان آزمایش رفتاری قابل پیشنهاد است.\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(44, 'generic_question', NULL, NULL, NULL, NULL, NULL, 'سؤال عمومی جلسه', '{\"text\":\"آخرین بار که الگوی ناخوشایندِ آشنایی بین شما تکرار شد، دقیقاً چه اتفاقی افتاد؟ از کدام لحظه «هوا عوض شد»؟\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(45, 'generic_question', NULL, NULL, NULL, NULL, NULL, 'سؤال عمومی جلسه', '{\"text\":\"در آن لحظه هر کدام واقعاً چه حسی داشتید و چه چیزی می‌خواستید بشنوید یا ببینید؟\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(46, 'generic_question', NULL, NULL, NULL, NULL, NULL, 'سؤال عمومی جلسه', '{\"text\":\"این الگو شبیه چه صحنه‌هایی از گذشتهٔ هر کدام از شماست؟\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(47, 'generic_question', NULL, NULL, NULL, NULL, NULL, 'سؤال عمومی جلسه', '{\"text\":\"چه رفتار کوچکی از طرف دیگری می‌تواند چرخه را قبل از داغ شدن متوقف کند؟\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15'),
(48, 'generic_question', NULL, NULL, NULL, NULL, NULL, 'سؤال عمومی جلسه', '{\"text\":\"برای هر کدام، «امن‌ترین راه» برای گفتن نیاز واقعی چیست؟\"}', 'medium', NULL, 'active', '2026-10-13 18:00:15', '2026-10-13 18:00:15', '2026-10-13 18:00:15');
