(1, NULL, 51, 59, 20, 22, 'بستهٔ زوجین — زهرا خجیر و رضا کاویان پور', 'draft', 30, '{\"engine_version\":\"1.0.0\",\"generated_at\":\"2026-10-11 17:41:23\",\"generated_by_admin_id\":1,\"case_id\":null,\"is_ysq_like\":false,\"priorities_a\":[{\"code\":\"ED\",\"title\":\"محرومیت هیجانی (Emotional Deprivation)\",\"raw_score\":36,\"max_score\":54,\"percentage\":60,\"severity\":\"high\"},{\"code\":\"MA\",\"title\":\"بی‌اعتمادی \\/ بدرفتاری (Mistrust \\/ Abuse)\",\"raw_score\":61,\"max_score\":102,\"percentage\":51.7999999999999971578290569595992565155029296875,\"severity\":\"moderate\"},{\"code\":\"NP\",\"title\":\"منفی‌بافی \\/ بدبینی (Negativity \\/ Pessimism)\",\"raw_score\":38,\"max_score\":66,\"percentage\":49.10000000000000142108547152020037174224853515625,\"severity\":\"moderate\"},{\"code\":\"AB\",\"title\":\"رهاشدگی \\/ بی‌ثباتی (Abandonment \\/ Instability)\",\"raw_score\":60,\"max_score\":108,\"percentage\":46.7000000000000028421709430404007434844970703125,\"severity\":\"moderate\"},{\"code\":\"PU\",\"title\":\"تنبیه‌جویی (Punitiveness)\",\"raw_score\":33,\"max_score\":60,\"percentage\":46,\"severity\":\"moderate\"}],\"priorities_b\":[{\"code\":\"PU\",\"title\":\"تنبیه‌جویی (Punitiveness)\",\"raw_score\":44,\"max_score\":60,\"percentage\":68,\"severity\":\"high\"},{\"code\":\"SS\",\"title\":\"ایثار \\/ فداکاری (Self-Sacrifice)\",\"raw_score\":61,\"max_score\":102,\"percentage\":51.7999999999999971578290569595992565155029296875,\"severity\":\"moderate\"},{\"code\":\"US\",\"title\":\"استانداردهای بی‌امان (Unrelenting Standards)\",\"raw_score\":48,\"max_score\":96,\"percentage\":40,\"severity\":\"moderate\"},{\"code\":\"ET\",\"title\":\"استحقاق \\/ خودبزرگ‌بینی (Entitlement \\/ Grandiosity)\",\"raw_score\":32,\"max_score\":66,\"percentage\":38.2000000000000028421709430404007434844970703125,\"severity\":\"low\"},{\"code\":\"AB\",\"title\":\"رهاشدگی \\/ بی‌ثباتی (Abandonment \\/ Instability)\",\"raw_score\":49,\"max_score\":108,\"percentage\":34.39999999999999857891