(4, NULL, 91, 98, 6, 8, 'بستهٔ زوجین — ماهرخ چناقچی و ماهان سرآهنگ', 'draft', 30, '{\"engine_version\":\"1.0.0\",\"generated_at\":\"2026-10-11 20:02:28\",\"generated_by_admin_id\":1,\"case_id\":null,\"is_ysq_like\":false,\"priorities_a\":[],\"priorities_b\":[{\"code\":\"SI\",\"title\":\"نقص \\/ شرم (Defectiveness \\/ Shame)\",\"raw_score\":60,\"max_score\":60,\"percentage\":100,\"severity\":\"high\"},{\"code\":\"FA\",\"title\":\"شکست (Failure)\",\"raw_score\":54,\"max_score\":54,\"percentage\":100,\"severity\":\"high\"},{\"code\":\"VH\",\"title\":\"آسیب‌پذیری نسبت به خطر (Vulnerability to Harm)\",\"raw_score\":72,\"max_score\":72,\"percentage\":100,\"severity\":\"high\"},{\"code\":\"EM\",\"title\":\"درآمیختگی \\/ خود جفت‌ونشده (Enmeshment \\/ Undeveloped Self)\",\"raw_score\":66,\"max_score\":66,\"percentage\":100,\"severity\":\"high\"},{\"code\":\"SB\",\"title\":\"سلطه‌پذیری (Subjugation)\",\"raw_score\":60,\"max_score\":60,\"percentage\":100,\"severity\":\"high\"}],\"cycles\":[],\"clinical_disclaimer\":\"این بسته ابزار پشتیبان تصمیم بالینی است و جایگزین ارزیابی، تشخیص و تجویز تخصصی درمانگر نیست.\"}', NULL, 1, NULL, '2026-10-11 20:02:28', '2026-10-11 20:02:28'),
