INSERT INTO `couple_package_items` (`id`, `package_id`, `sort_order`, `source`, `joma_code`, `title`, `description`, `instructions`, `frequency`, `unit_fa`, `target_value`, `sticker`, `color`, `reason`, `measurement_note`, `created_at`) VALUES
(1, 1, 0, 'joma', 'ACT046', 'بازسازی صمیمیت عاطفی', '۱۵ دقیقه نزدیکی عاطفی روزانه؛ اشتراک احساس، نه برنامه‌ریزی.', 'روزی ۱۵ دقیقه دربارهٔ «احساسات درون‌تان» با هم حرف بزنید (دلم می‌خواهد، می‌ترسم از، خوشحالم از...). شنونده فقط تکرار و تأیید می‌کند؛ نصیحت و قضاوت ممنوع.', 'DAILY', 'دقیقه', 15.00, 'heart', '#db2777', 'طرحوارهٔ «محرومیت هیجانی (Emotional Deprivation)» در همسر الف (۶۰٪ — شدید)', '', '2026-10-11 17:41:23'),
(2, 1, 1, 'joma', 'ACT079', 'تمرین روزانه اتصال عاطفی', 'روزی یک لحظهٔ اتصال کوتاه و هدفمند.', 'روزی یک «لحظهٔ اتصال» ۶۰ ثانیه‌ای: آغوش کامل، نگاه در چشم با لبخند، یا یک جملهٔ «تو برام مهمی». زمان ثابت روزانه انتخاب کنید (قبل خواب بهترین است).', 'DAILY', '—', 1.00, 'link', '#db2777', 'طرحوارهٔ «محرومیت هیجانی (Emotional Deprivation)» در همسر الف (۶۰٪ — شدید)', '', '2026-10-11 17:41:23'),
(3, 1, 2, 'joma', 'ACT058', 'تقویت محبت و توجه روزانه', 'روزی یک رفتار محبت‌آمیز کوچک و مشخص انجام دهید.', 'روزی یک عمل محبت کوچک از فهرست «زبان‌های عشق» همسرتان انجام دهید (چای، پیام کوتاه، آغوش ۲۰ ثانیه‌ای). رفتار را در تقویم تیک بزنید تا الگوی دوسویه شدنش دیده شود.', 'DAILY', '—', 1.00, 'heart', '#db2777', 'طرحوارهٔ «محرومیت هیجانی (Emotional Deprivation)» در همسر الف (۶۰٪ — شدید)', '', '2026-10-11 17:41:23'),
(4, 1, 3, 'joma', 'ACT054', 'بازسازی اعتماد آسیب‌دیده', '۲۰ دقیقه هفتگی روی ترمیم اعتماد؛ شفافیت و قول‌های کوچک.', 'هفته‌ای ۲۰ دقیقه: هر نفر یک «قول کوچک قابل‌اندازه‌گیری» برای هفتهٔ بعد می‌دهد و قول هفتهٔ قبل بررسی می‌شود (انجام شد/نشد و چرا). شفافیت دربارهٔ برنامه و ارتباطات بخشی از تمرین است.', 'WEEKLY', 'دقیقه', 20.00, 'shield', '#0d9488', 'طرحوارهٔ «بی‌اعتمادی / بدرفتاری (Mistrust / Abuse)» در همسر الف (۵۱.۸٪ — متوسط)', '', '2026-10-11 17:41:23'),
(5, 1, 4, 'joma', 'ACT066', 'مقابله با حسادت و ناامنی عاطفی', 'روزی یک آشکارسازی یا پاسخ آرام به ترس‌های ناامنی.', 'شریکِ نگران: روزی یک ترس ناامنی را با قالب «وقتی... نگران می‌شوم» بگوید (نه اتهام). شریک دیگر: روزی یک رفتار شفاف‌کنندهٔ داوطلبانه انجام دهد. هر دو در تقویم تیک بزنند.', 'DAILY', '—', 1.00, 'shield', '#0d9488', 'طرحوارهٔ «بی‌اعتمادی / بدرفتاری (Mistrust / Abuse)» در همسر الف (۵۱.۸٪ — متوسط)', '', '2026-10-11 17:41:23'),
(6, 1, 5, 'joma', 'ACT057', 'شناخت طرحواره‌های مؤثر بر رابطه', '۲۰ دقیقه هفتگی: کدام طرحوارهٔ کدام‌تان در رابطه فعال شد؟', 'هفته‌ای ۲۰ دقیقه یک موقعیت هیجانی هفته را انتخاب کنید و سه سؤال: کدام طرحوارهٔ قدیمی من فعال شد؟ از کجا آمده؟ همسرم چطور می‌تواند در آن لحظه به من کمک کند؟ پاسخ‌ها را برای هم بخوانید.', 'WEEKLY', 'دقیقه', 20.00, 'brain', '#7c3aed', 'طرحوارهٔ «بی‌اعتمادی / بدرفتاری (Mistrust / Abuse)» در همسر الف (۵۱.۸٪ — متوسط)', '', '2026-10-11 17:41:23'),
(7, 1, 6, 'joma', 'ACT067', 'مدیریت افکار منفی درباره همسر', 'روزی یک فکر منفی دربارهٔ همسر را بنویسید و بازآزمایی کنید.', 'روزی یک فکر منفی («او فقط به فکر خودش است») بنویسید، شواهد موافق/مخالفش را بیاورید و یک تفسیر جایگزین منصفانه بنویسید. در پایان هفته، سه تفسیر جایگزین را با هم بخوانید.', 'DAILY', '—', 1.00, 'cloud', '#7c3aed', 'طرحوارهٔ «منفی‌بافی / بدبینی (Negativity / Pessimism)» در همسر الف (۴۹.۱٪ — متوسط)', '', '2026-10-11 17:41:23'),
(8, 1, 7, 'joma', 'ACT074', 'تقویت نقاط قوت رابطه', 'جلسهٔ هفتگی جشنِ نقاط قوت: چه چیزیمان خوب کار می‌کند؟', 'هفته‌ای یک بار هر کدام سه چیز از رابطه را که «خوب کار می‌کند» نام ببرید و یکی را برای هفتهٔ بعد تقویت کنید. مغز زوج‌های موفق دائماً «چیزی که کار می‌کند» را می‌بیند.', 'WEEKLY', '—', 1.00, 'star', '#f59e0b', 'طرحوارهٔ «منفی‌بافی / بدبینی (Negativity / Pessimism)» در همسر الف (۴۹.۱٪ — متوسط)', '', '2026-10-11 17:41:23'),
(9, 1, 8, 'joma', 'ACT080', 'ارزیابی ماهانه سلامت رابطه', 'هر ماه یک نمره و یک گفت‌وگو دربارهٔ وضعیت رابطه.', 'اول هر ماه هر دو جداگانه به رابطه نمرهٔ ۱ تا ۱۰ بدهید و سه سؤال را جواب دهید: بهترین اتفاق؟ دغدغهٔ اصلی؟ یک درخواست مشخص. بعد نمره‌ها و پاسخ‌ها را با هم مرور کنید.', 'MONTHLY', '—', 1.00, 'chart', '#0d9488', 'طرحوارهٔ «منفی‌بافی / بدبینی (Negativity / Pessimism)» در همسر الف (۴۹.۱٪ — متوسط)', '', '2026-10-11 17:41:23'),
(10, 1, 9, 'outside', 'OUT_SAFE_WINDOW', 'پنجرهٔ امن: گفت‌وگوی ساختاریافتهٔ ۲۰ دقیقه‌ای', 'قالب گفت‌وگوی درمانی با زمان‌بندی مشخص برای زوج‌هایی که ترسِ رهاشدگی یا بی‌اعتمادی فعال است.', 'هر شب ۲۰ دقیقه با سه بخش: ۵ دقیقه هر نفر «سختی امروز من» (شنونده فقط خلاصه‌گیری)، ۵ دقیقه «یک نیاز از همسرم»، ۵ دقیقه «یک تشکر». ساعت ثابت بگذارید؛ اگر یک شب از دست رفت جبرانِ «دو برابری» لازم نیست، فردا ادامه دهید.', 'DAILY', 'دقیقه', 20.00, 'clipboard', '#b45309', 'نیاز بالینی فعال (AB، ED، MA) — معادل آن در کتابخانهٔ جوما موجود نیست', 'سنجش: تعداد دقیقه در روز (هدف ۲۰ دقیقه) + تیک انجام در تقویم.', '2026-10-11 17:41:23'),
(11, 1, 10, 'outside', 'OUT_TIMEOUT', 'قرارداد تایم‌اوت ایمن (وقفهٔ تحریک طرحواره)', 'پروتکل توقف ایمن هنگام روشن‌شدن خشم/کنترل‌گری/تنبیه‌جویی؛ جوما معادل دقیق این پروتکل را ندارد.', 'هر دو زوج قرارداد را امضا می‌کنند: هر کدام حس کرد دکمه‌اش فشرده شد، با علامت توافقی (کلمهٔ «تایم‌اوت») وقفهٔ ۲۰-۳۰ دقیقه‌ای می‌گیرد و متعهد می‌شود «برگردد» (زمان دقیق بگوید). در دفترچه: محرک، نشانهٔ جسمی، مدت وقفه، نحوهٔ بازگشت.', 'DAILY', 'بار', 1.00, 'clipboard', '#b45309', 'نیاز بالینی فعال (ET، PU) — معادل آن در کتابخانهٔ جوما موجود نیست', 'سنجش: تعداد «بار» در روز (هدف: ۱ ثبتِ درست، حتی اگر وقفه لازم نشد) + مدت وقفه.', '2026-10-11 17:41:23'),
(12, 1, 11, 'outside', 'OUT_GREY', 'عرصهٔ خاکستری: تمرین پذیرشِ تفاهم‌نرفته', 'برای استانداردهای بی‌امان و منفی‌بافی: تمرین «موافقت با تفاوت» که در جوما نیست.', 'هفته‌ای ۱۵ دقیقه یک اختلافِ حل‌ناشدنیِ شناخته‌شده را انتخاب کنید و فقط تمرین کنید «بدون حل‌کردن» درباره‌اش آرام حرف بزنید: هر نفر نظر دیگری را منصفانه خلاصه کند و بگوید «این تفاوت ماست و من تو را با این تفاوت می‌خواهم». حل‌کردن ممنوع است — خودِ پذیرش، تمرین است.', 'WEEKLY', 'دقیقه', 15.00, 'clipboard', '#b45309', 'نیاز بالینی فعال (US، NP) — معادل آن در کتابخانهٔ جوما موجود نیست', 'سنجش: «دقیقه» در هفته (هدف ۱۵) + نمرهٔ تنش ۰ تا ۱۰ قبل و بعد.', '2026-10-11 17:41:23'),
(13, 1, 12, 'outside', 'OUT_SYMMETRY', 'بازی نقش متقارن (توازن سلطه‌پذیری/فداکاری)', 'برای زوج‌هایی که یک‌طرف بیش از حد می‌دهد و دیگری دریافت می‌کند؛ جوما معادل ساختاریافته ندارد.', 'هفته‌ای ۲۰ دقیقه نقش‌ها عوض می‌شود: فردِ «همیشه‌دهنده» یک درخواست صریح مطرح می‌کند و فردِ دیگر آن را «کامل» انجام می‌دهد؛ بعد جای نقش‌ها در یک تصمیم کوچک عوض شود. هدف تجربهٔ ذهنیِ تقارن است، نه تسویه‌حساب.', 'WEEKLY', 'دقیقه', 20.00, 'clipboard', '#b45309', 'نیاز بالینی فعال (SS) — معادل آن در کتابخانهٔ جوما موجود نیست', 'سنجش: «بار» در هفته (هدف ۱) + ثبت اینکه درخواستِ دهنده چند «کم‌تر از حد نیاز» کوچک شد (تمرین بزرگ‌کردن درخواست).', '2026-10-11 17:41:23'),
(40, 4, 0, 'joma', 'ACT072', 'شناخت نقش خودم در مشکلات رابطه', '۱۰ دقیقه روزانه: سهم من در تنش امروز چه بود؟', 'روزی ۱۰ دقیقه دربارهٔ یک تعامل روز: من چه کردم که چرخه شعله گرفت؟ کدام ترس یا طرحوارهٔ خودم وسط بود؟ یک جایگزین کوچک برای فردا بنویسید. این تمرین فقط «سهم خود» است؛ سرزنشِ خود و دیگری ممنوع.', 'DAILY', 'دقیقه', 10.00, 'mirror', '#7c3aed', 'طرحوارهٔ «نقص / شرم (Defectiveness / Shame)» در همسر ب (۱۰۰٪ — شدید)', '', '2026-10-11 20:02:28'),
(41, 4, 1, 'joma', 'ACT017', 'قدردانی از همسر', 'هر روز یک قدردانی مشخص و غیرکلی از همسر بیان کنید.', 'روزی یک بار، یک رفتار مشخص از همسر را که برایتان ارزشمند بود نام ببرید و بگویید چه احساسی در شما ایجاد کرد. قدردانی باید «مشخص» باشد (نه «ممنون که هستی») و رودررو یا در پیام بیان شود.', 'DAILY', '—', 1.00, 'heart', '#e11d48', 'طرحوارهٔ «نقص / شرم (Defectiveness / Shame)» در همسر ب (۱۰۰٪ — شدید)', '', '2026-10-11 20:02:28'),
(42, 4, 2, 'joma', 'ACT069', 'کنار آمدن با سردی عاطفی', 'روزی یک اقدام گرم‌کننده به‌جای شکایت از سردی.', 'به‌جای نشانه‌گیری به سردیِ دیگری، روزی یک «اقدام گرم» کوچک انجام دهید (تماس چشمی، جملهٔ محبت، لمس کوتاه) و سردیِ خودتان را هم در دفترچه ثبت کنید. سردی اغلب دوسویه خاموش می‌شود.', 'DAILY', '—', 1.00, 'snow', '#0284c7', 'طرحوارهٔ «نقص / شرم (Defectiveness / Shame)» در همسر ب (۱۰۰٪ — شدید)', '', '2026-10-11 20:02:28'),
(43, 4, 3, 'joma', 'ACT074', 'تقویت نقاط قوت رابطه', 'جلسهٔ هفتگی جشنِ نقاط قوت: چه چیزیمان خوب کار می‌کند؟', 'هفته‌ای یک بار هر کدام سه چیز از رابطه را که «خوب کار می‌کند» نام ببرید و یکی را برای هفتهٔ بعد تقویت کنید. مغز زوج‌های موفق دائماً «چیزی که کار می‌کند» را می‌بیند.', 'WEEKLY', '—', 1.00, 'star', '#f59e0b', 'طرحوارهٔ «شکست (Failure)» در همسر ب (۱۰۰٪ — شدید)', '', '2026-10-11 20:02:28'),
