INSERT INTO `test_results` (`id`, `session_id`, `user_id`, `test_id`, `test_version`, `total_score`, `dimension_scores_json`, `overall_category`, `overall_severity`, `short_interpretation`, `scientific_audit_trail_json`, `user_visible`, `created_at`) VALUES
