(50, 54, 20, 4, '2.0', 188.00, '[{\"id\":62,\"code\":\"factor_a\",\"title\":\"عامل A: مردم‌آمیزی \\/ گرم‌خویی (Warmth)\",\"description\":\"سنجش گرما در مراودات، محبت، صمیمیت و مردم‌داری در برابر کناره‌گیری\",\"min_score\":10,\"max_score\":40,\"color_hex\":\"#f59e0b\",\"raw_score\":12,\"item_count\":12,\"average_score\":1,\"percentage\":6.70000000000000017763568394002504646778106689453125,\"category_name\":\"عادی \\/ بهنجار\",\"severity_level\":\"normal\",\"interpretation\":\"نمره کسب‌شده در این بعد برابر با ۱۲ می‌باشد.\"},{\"id\":63,\"code\":\"factor_b\",\"title\":\"عامل B: استدلال و هوش سیال (Reasoning)\",\"description\":\"سنجش توانایی حل مسئله، تفکر انتزاعی و سرعت یادگیری مفاهیم نو\",\"min_score\":10,\"max_score\":40,\"color_hex\":\"#3b82f6\",\"raw_score\":12,\"item_count\":12,\"average_score\":1,\"percentage\":6.70000000000000017763568394002504646778106689453125,\"category_name\":\"عادی \\/ بهنجار\",\"severity_level\":\"normal\",\"interpretation\":\"نمره کسب‌شده در این بعد برابر با ۱۲ می‌باشد.\"},{\"id\":64,\"code\":\"factor_c\",\"title\":\"عامل C: پایداری هیجانی (Emotional Stability)\",\"description\":\"سنجش قدرت ایگو، خونسردی، سازگاری و ثبات در برابر تنش‌ها\",\"min_score\":10,\"max_score\":40,\"color_hex\":\"#10b981\",\"raw_score\":13,\"item_count\":12,\"average_score\":1.0800000000000000710542735760100185871124267578125,\"percentage\":10,\"category_name\":\"عادی \\/ بهنجار\",\"severity_level\":\"normal\",\"interpretation\":\"نمره کسب‌شده در این بعد برابر با ۱۳ می‌باشد.\"},{\"id\":65,\"code\":\"factor_e\",\"title\":\"عامل E: سلطه‌گری \\/ قاطعیت (Dominance)\",\"description\":\"سنجش تمایل به رهبری، اظهار وجود، ابراز قدرت و رقابت‌جویی\",\"min_score\":10,\"max_score\":40,\"color_hex\":\"#ef4444\",\"raw_score\":12,\"item_count\":12,\"average_score\":1,\"percentage\":6.70000000000000017763568394002504646778106689453125,\"category_name\":\"عادی \\/ بهنجار\",\"severity_level\":\"normal\",\"interpretation\":\"نمره کسب‌شده در این بعد برابر با ۱۲ می‌باشد.\"},{\"id\":66,\"code\":\"factor_f\",\"title\":\"عامل F: سرزندگی و نشاط (Liveliness)\",\"description\":\"سنجش خودانگیختگی، برون‌ریزی شادی، خوش‌بینی و انرژی رفتاری\",\"min_score\":10,\"max_score\":40,\"color_hex\":\"#eab308\",\"raw_score\":13,\"item_count\":12,\"average_score\":1.0800000000000000710542735760100185871124267578125,\"percentage\":10,\"category_name\":\"عادی \\/ بهنجار\",\"severity_level\":\"normal\",\"interpretation\":\"نمره کسب‌شده در این بعد برابر با ۱۳ می‌باشد.\"},{\"id\":67,\"code\":\"factor_g\",\"title\":\"عامل G: قانون‌گرایی و وجدان (Rule-Consciousness)\",\"description\":\"سنجش پایبندی به قوانین، انضباط اخلاقی و مسئولیت‌پذیری شغلی\",\"min_score\":10,\"max_score\":40,\"color_hex\":\"#0d9488\",\"raw_score\":12,\"item_count\":12,\"average_score\":1,\"percentage\":6.70000000000000017763568394002504646778106689453125,\"category_name\":\"عادی \\/ بهنجار\",\"severity_level\":\"normal\",\"interpretation\":\"نمره کسب‌شده در این بعد برابر با ۱۲ می‌باشد.\"},{\"id\":68,\"code\":\"factor_h\",\"title\":\"عامل H: جسارت اجتماعی (Social Boldness)\",\"description\":\"سنجش نترسیدن از جمع، شجاعت، پیشقدمی در روابط و ماجراجویی\",\"min_score\":10,\"max_score\":40,\"color_hex\":\"#8b5cf6\",\"raw_score\":12,\"item_count\":12,\"average_score\":1,\"percentage\":6.70000000000000017763568394002504646778106689453125,\"category_name\":\"عادی \\/ بهنجار\",\"severity_level\":\"normal\",\"interpretation\":\"نمره کسب‌شده در این بعد برابر با ۱۲ می‌باشد.\"},{\"id\":69,\"code\":\"factor_i\",\"title\":\"عامل I: حساسیت هیجانی (Sensitivity)\",\"description\":\"سنجش لطافت طبع، درک هنری، حساسیت عاطفی و شهود در برابر عمل‌گرایی\",\"min_score\":10,\"max_score\":40,\"color_hex\":\"#ec4899\",\"raw_score\":13,\"item_count\":12,\"average_score\":1.0800000000000000710542735760100185871124267578125,\"percentage\":10,\"category_name\":\"عادی \\/ بهنجار\",\"severity_level\":\"normal\",\"interpretation\":\"نمره کسب‌شده در این بعد برابر با ۱۳ می‌باشد.\"},{\"id\":70,\"code\":\"factor_l\",\"title\":\"عامل L: هوشیاری و سو