INSERT INTO `test_sources` (`id`, `test_id`, `citation_title`, `authors`, `year`, `doi`, `pmid`, `url`, `notes`) VALUES
(1, 1, 'Minnesota Multiphasic Personality Inventory-2 (MMPI-2 Full Form - 567 Items)', 'Butcher, J. N., Dahlstrom, W. G., Graham, J. R., Tellegen, A., & Kaemmer, B.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Butcher, J. N., Dahlstrom, W. G., Graham, J. R., Tellegen, A., & Kaemmer, B. (1989). MMPI-2: Manual for administration and scoring. University of Minnesota Press. هنجاریابی ایرانی: دکتر پوراعتماد، دکتر براهنی، دکتر منصور و دکتر دادستان'),
(2, 2, 'Revised NEO Personality Inventory (NEO-PI-R Full 240-Item Form)', 'Costa, P. T., & McCrae, R. R.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Costa, P. T., & McCrae, R. R. (1992). Revised NEO Personality Inventory (NEO PI-R) and NEO Five-Factor Inventory (NEO-FFI) professional manual. Psychological Assessment Resources. هنجاریابی ایرانی: دکتر حق‌شناس (۱۳۸۵) و دکتر گروسی فرشی'),
(3, 3, 'Young Schema Questionnaire - Long Form 3 (YSQ-L3 Full 232-Item Form)', 'Young, J. E., Klosko, J. S., & Weishaar, M. E.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Young, J. E., Klosko, J. S., & Weishaar, M. E. (2003). Schema therapy: A practitioner\'s guide. Guilford Press. هنجاریابی ایرانی: دکتر یوسفی، دکتر بهرامی و همکاران (۱۳۸۸)'),
(4, 4, 'Cattell 16 Personality Factor Questionnaire (16PF Fifth Edition - 185 Items)', 'Russell, M. T., & Karol, D. L.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Russell, M. T., & Karol, D. L. (1994). 16PF Fifth Edition Administrator\'s Manual. Institute for Personality and Ability Testing. هنجاریابی ایرانی: دکتر کرمی و دکتر طباطبایی (۱۳۸۵)'),
(5, 5, 'Couples Satisfaction Index (CSI-32 Full 32-Item Form)', 'Funk, J. L., & Rogge, R. D.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Funk, J. L., & Rogge, R. D. (2007). Testing the ruler with item response theory: Increasing precision of measurement for relationship satisfaction with the Couples Satisfaction Index. Journal of Family Psychology, 21(4), 572-583. هنجاریابی ایرانی: فروزش یکتا و همکاران (۲۰۱۷)'),
(6, 6, 'Depression Anxiety Stress Scales (DASS-21)', 'Lovibond, S.H. & Lovibond, P.F.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Lovibond, S.H. & Lovibond, P.F. (1995). Manual for the Depression Anxiety Stress Scales. (2nd. Ed.) Sydney: Psychology Foundation. هنجاریابی ایرانی: دکتر صاحبی و همکاران (۱۳۸۴)'),
(7, 7, 'Generalized Anxiety Disorder 7-item Scale (GAD-7)', 'Spitzer, R. L., Kroenke, K., Williams, J. B., & Löwe, B.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Spitzer, R. L., Kroenke, K., Williams, J. B., & Löwe, B. (2006). A brief measure for assessing generalized anxiety disorder: the GAD-7. Archives of Internal Medicine, 166(10), 1092-1097. هنجاریابی ایرانی: نائینیان و همکاران (۱۳۹۰)'),
(8, 8, 'Patient Health Questionnaire-9 (PHQ-9)', 'Kroenke, K., Spitzer, R. L., & Williams, J. B.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Kroenke, K., Spitzer, R. L., & Williams, J. B. (2001). The PHQ-9: validity of a brief depression severity measure. Journal of General Internal Medicine, 16(9), 606-613. هنجاریابی ایرانی: خمسه و همکاران (۱۳۹۰) و دادفر و همکاران (۲۰۱۸)'),
(9, 9, 'Rosenberg Self-Esteem Scale (RSES)', 'Rosenberg, M.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Rosenberg, M. (1965). Society and the adolescent self-image. Princeton, NJ: Princeton University Press. هنجاریابی ایرانی: محمدی (۱۳۸۴) و رجبی و بهلول (۱۳۸۶)'),
(10, 10, 'Satisfaction with Life Scale (SWLS)', 'Diener, E., Emmons, R. A., Larsen, R. J., & Griffin, S.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Diener, E., Emmons, R. A., Larsen, R. J., & Griffin, S. (1985). The Satisfaction with Life Scale. Journal of Personality Assessment, 49(1), 71-75. هنجاریابی ایرانی: بیانی، کوچکی و گودرزی (۱۳۸۶) و معروف‌زاده و همکاران (۲۰۱۶)'),
(11, 11, 'Experiences in Close Relationships-Revised (ECR-R)', 'Fraley, R. C., Waller, N. G., & Brennan, K. A.', '2000', NULL, NULL, 'https://mirbolouki.com', 'Fraley, R. C., Waller, N. G., & Brennan, K. A. (2000). An item response theory analysis of the Experiences in Close Relationships-Revised (ECR-R) measure of adult attachment. Journal of Personality and Social Psychology, 78(2), 350-365. هنجاریابی ایرانی: دکتر بشارت (۱۳۹۰) و دهقانی و همکاران'),
(18, 12, 'Schema therapy: A practitioner guide. Guilford Press.', 'Young, J. E., Klosko, J. S., & Weishaar, M. E.', '2003', NULL, NULL, NULL, 'منبع اصلی نظریه و تکنیک‌های طرحواره‌درمانی'),
(19, 12, 'Young Schema Questionnaire – Long Form 3 (YSQ-L3 / YEMSQ). Schema Therapy Institute.', 'Young, J. E.', '2005', NULL, NULL, NULL, 'کتابچه راهنمای روان‌سنجی آزمون طرحواره‌های یانگ'),
(20, 12, 'بررسی ویژگی‌های روان‌سنجی پرسشنامه طرحواره‌های یانگ در جمعیت ایرانی.', 'دکتر لادن فتی، دکتر محمدعلی لواسانی، دکتر محمدعلی مظاهری', '۱۳۸۹', NULL, NULL, NULL, 'هنجاریابی دانشگاهی نسخه فارسی');
